import numpy as np
import pandas as pd
from scipy.optimize import least_squares, brentq
from sklearn.model_selection import KFold
from sklearn.metrics import mean_squared_error, mean_absolute_error
from catboost import CatBoostRegressor
D = pd.read_csv("alloy_pair_target_train.csv")
elements = list(D.columns[:12])
nums = elements + ["solutionizing_temp", "aging_temp", "aging_time", "cooling_rate"]
cats = ["heat_treatment", "route"]
centers, scales = D[nums].mean().values, D[nums].std().values

def design(d):
    z = (d[nums].values-centers)/scales
    cat = np.column_stack([d.heat_treatment.eq(v) for v in ["quenched", "quench_temper", "solution_aged"]] + [d.route.eq(v) for v in ["cast", "wrought"]])
    return np.column_stack([np.ones(len(d)), z, z*z, cat])

def coords(d):
    return d[["Nb", "solutionizing_temp", "cooling_rate"]].values

def bump(x, p):
    return np.exp(-0.5*np.sum(((x-p[:3])/p[3:6])**2, axis=1))

def fit(d, initial=None):
    a, x, y = design(d), coords(d), d.target.values
    coef = np.linalg.lstsq(a, y, rcond=None)[0]
    p0 = np.r_[coef, [0.4145, 1134.4, 39.52, 0.0752, 25.62, 7.72, 630.8]] if initial is None else initial
    lower = np.r_[np.full(a.shape[1], -np.inf), [0.25, 1080, 20, 0.025, 8, 2, 0]]
    upper = np.r_[np.full(a.shape[1], np.inf), [0.6, 1180, 60, 0.2, 70, 25, 1200]]
    def residual(p):
        return a@p[:-7] + p[-1]*bump(x, p[-7:])-y
    return least_squares(residual, p0, bounds=(lower,upper), x_scale="jac", max_nfev=800, ftol=1e-9, xtol=1e-9, gtol=1e-9).x

def predict(d,p):
    return design(d)@p[:-7] + p[-1]*bump(coords(d),p[-7:])

def metrics(y,p):
    return {"rmse": float(np.sqrt(mean_squared_error(y,p))), "mae": float(mean_absolute_error(y,p))}

kf=KFold(n_splits=5,shuffle=True,random_state=42)
oof={k:np.zeros(len(D)) for k in ["quadratic","hotspot","catboost"]}
folds=[]
for tr,te in kf.split(D):
    coef=np.linalg.lstsq(design(D.iloc[tr]),D.target.iloc[tr],rcond=None)[0]
    oof["quadratic"][te]=design(D.iloc[te])@coef
    model=fit(D.iloc[tr]); folds.append(model)
    oof["hotspot"][te]=predict(D.iloc[te],model)
    cb=CatBoostRegressor(iterations=900,depth=4,learning_rate=0.035,l2_leaf_reg=5,loss_function="RMSE",verbose=False,random_seed=42,thread_count=2,allow_writing_files=False)
    cb.fit(D.iloc[tr][nums+cats],D.target.iloc[tr],cat_features=cats)
    oof["catboost"][te]=cb.predict(D.iloc[te][nums+cats])
    print("FOLD hotspot",model[-7:],flush=True)
for k,v in oof.items(): print("VALIDATION",k,metrics(D.target,v),flush=True)
model=fit(D); pred=predict(D,model)
print("FULL PARAMS",model[-7:]); print("TRAIN",metrics(D.target,pred)); print("CATEGORY COEF",model[-12:-7])
res=D.target.values-pred
print("LARGEST RESIDUALS"); print(D.assign(prediction=pred,residual=res).iloc[np.argsort(abs(res))[-15:]].to_string())
print("NUMERIC COEFFICIENTS")
for i,n in enumerate(nums): print(n,model[1+i]/scales[i],model[17+i]/scales[i]**2)
candidates=[]
for idx in [107,176,5,38,127]:
    for feat in ["Nb","solutionizing_temp","cooling_rate"]:
        row=D.iloc[[idx]].copy(); row["route"]="wrought"; row["heat_treatment"]="quench_temper"
        baseline=float(predict(row,model)[0])
        grid=np.linspace(D[feat].min(),D[feat].max(),301)
        def value(v):
            row[feat]=v
            return float(predict(row,model)[0]-1051)
        values=[value(v) for v in grid]
        for lo,hi,flo,fhi in zip(grid[:-1],grid[1:],values[:-1],values[1:]):
            if flo*fhi<0:
                root=brentq(value,lo,hi); row[feat]=root
                fp=[float(predict(row,m)[0]) for m in folds]
                candidates.append((np.std(fp),idx,feat,root,baseline,fp,row.copy()))
candidates.sort(key=lambda t:t[0])
for spread,idx,feat,root,baseline,fp,row in candidates: print("CANDIDATE",idx,feat,root,"start",baseline,"fold std",spread,"folds",fp,flush=True)
rng=np.random.default_rng(17)
boots=[]
for b in range(100):
    boots.append(fit(D.iloc[rng.integers(0,len(D),len(D))],model))
    if b%25==0: print("BOOT FIT",b,flush=True)
for spread,idx,feat,root,baseline,fp,row in candidates[:12]:
    bp=np.array([predict(row,m)[0] for m in boots])
    print("BOOTSTRAP",idx,feat,root,"mean",bp.mean(),"median",np.median(bp),"std",bp.std(),"quantiles",np.quantile(bp,[0.05,0.25,0.75,0.95]),flush=True)
print("ANCHOR 107 true fitted CV",D.target.iloc[107],pred[107],oof["hotspot"][107])
print("TOP RECIPE",candidates[0][-1][nums+cats].to_dict(orient="records")[0])
'

